// Get booking_time from the correct path
const bookingTime = $input.item.json.body.message.toolCalls[0].function.arguments.booking_time;

// Parse the booking time
const startDate = new Date(bookingTime);

// Calculate end date (72 hours later)
const endDate = new Date(startDate);
endDate.setHours(endDate.getHours() + 72);

// Format dates as YYYY-MM-DD
const formatDate = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
};

return {
  json: {
    start_date: formatDate(startDate),
    end_date: formatDate(endDate)
  }
};

