// Get slots data from HTTP Request node (previous node)
const slotsData = $input.item.json.data;

// Get booking_time from Webhook node
const bookingTime = $('Webhook').item.json.body.message.toolCalls[0].function.arguments.booking_time;

// Convert booking_time "2026-02-02 14:00" to comparable format
// Extract date and time parts
const [datePart, timePart] = bookingTime.split(' ');
const searchTime = `${datePart}T${timePart}:00`;

// Check if the booking time exists in any available slot
let isAvailable = false;

// Loop through each date in the slots data
for (const date in slotsData) {
  const slots = slotsData[date];

  // Check each slot for that date
  for (const slot of slots) {
    // slot.start format: "2026-02-02T14:00:00.000+02:00"
    // We need to compare just the date and time portion
    if (slot.start.startsWith(searchTime)) {
      isAvailable = true;
      break;
    }
  }

  if (isAvailable) break;
}

return {
  json: {
    available: isAvailable,
    requested_time: bookingTime
  }
};

