n15.text:
// Get slots data from HTTP Request1 node
const slotsData = $('HTTP Request1').item.json.data;

// Get new_booking from Webhook node
const newBooking = $('Webhook').item.json.body.message.toolCalls[0].function.arguments.new_booking;

// Parse the requested booking time
const requestedTime = new Date(newBooking.replace(' ', 'T'));

// Collect all available slots into a flat array with their Date objects
const allSlots = [];
for (const date in slotsData) {
  for (const slot of slotsData[date]) {
    allSlots.push({
      start: slot.start,
      dateObj: new Date(slot.start)
    });
  }
}

// Find the closest slot to the requested time
let closestSlot = null;
let smallestDiff = Infinity;

for (const slot of allSlots) {
  const diff = Math.abs(slot.dateObj - requestedTime);
  if (diff < smallestDiff) {
    smallestDiff = diff;
    closestSlot = slot;
  }
}

// Format the closest slot as YYYY-MM-DD hh:mm
const formatSlot = (date) => {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  const hours = String(date.getHours()).padStart(2, '0');
  const minutes = String(date.getMinutes()).padStart(2, '0');
  return `${year}-${month}-${day} ${hours}:${minutes}`;
};

return {
  json: {
    closest_available_slot: closestSlot ? formatSlot(closestSlot.dateObj) : null,
    requested_time: newBooking,
    original_slot_iso: closestSlot ? closestSlot.start : null
  }
};

